product.classList.toggle("active"); // drugie wywolanie: USUWA klase 'active' (bo juz byla)

const product = document.getElementById("product-2");
console.log(product.className); // np. "card"
product.className = "card active"; // nadpisuje WSZYSTKIE klasy naraz

const cards = document.querySelectorAll(".card");
cards.forEach((c, i) => {
  c.classList.toggle("highlight", i % 2 === 0);
});

const product = document.getElementById("product-2");
product.classList.add("active");
product.style.border = "2px solid #2e7d32";
